INSERT INTO blog_posts (id, slug, status, region_id, title, title_highlight, summary, lede, destination, cta_title, cover_url, cover_url_small, cover_alt, featured, body, reading_minutes)
VALUES ('dcf08d05-1b79-472a-9223-eec105b97912', 'escala-em-istambul', 'draft', 'europa', 'Escala em Istambul: o que dá para fazer em 10, 14 ou 19 horas', '10, 14 ou 19 horas', 'Como transformar uma escala longa em passeio: a conta do tempo, o caminho do aeroporto à cidade, roteiros para 10, 14 e 19 horas, valores conferidos em outubro de 2026 e o guia em PDF para baixar de graça.', 'Brasileiro entra na Turquia sem visto por até 90 dias. A conta do tempo diz se a sua escala vira passeio, e o guia completo vai no celular.', 'Istambul', NULL, '/assets/blog/istambul-escala.jpg', '/assets/blog/istambul-escala-m.jpg', 'Pôr do sol sobre as águas de Istambul, com o sol rente ao horizonte, um barco pequeno à esquerda e o céu alaranjado sob nuvens escuras', 0, '[{"t":"pdf","href":"/guias/escala-em-istambul.pdf","note":"PDF de 13 páginas, feito para ler no celular. Grátis, sem cadastro."},{"t":"p","text":"Brasileiro entra na Turquia sem visto, por até 90 dias, e uma escala longa vira passeio **se a conta do tempo fechar**. O aeroporto de Istambul é longe do centro: o que decide o passeio não é o total de horas entre os voos, e sim **quantas horas sobram depois de sair e voltar**."},{"t":"tip","items":["**Anote o horário de pouso e o do próximo voo.**","**Faça a conta do tempo** (Passo 1, logo abaixo).","**Escolha o roteiro que cabe:** 10, 14 ou 19 horas."],"title":"Como usar este guia"},{"t":"whatsapp","title":"Cotar passagem com escala em Istambul","text":"Envie a sua cidade de saída, o mês da viagem e o número de pessoas. A Rota Certa encontra a sua passagem, com a escala que cabe no seu passeio.","label":"Quero cotar minha passagem","message":"Oi, Rota Certa! Vi o guia Escala em Istambul e quero cotar uma passagem com escala em Istambul."},{"t":"afiliado"},{"t":"h","text":"A conta do tempo","label":"Passo 1"},{"t":"p","text":"**Tempo na cidade = tempo entre os voos, menos o que você gasta só para sair e voltar.**"},{"t":"ul","items":["**Imigração e saída do terminal:** 1 h 30","**Ida, do aeroporto ao centro:** 1 h 20","**Volta, do centro ao aeroporto:** 1 h 20","**Estar no aeroporto antes do voo:** 3 h","**Margem de segurança:** 30 min","**Total que sai da sua escala:** 7 h 40"]},{"t":"tip","items":["Esses tempos são estimativas nossas para planejar a margem. **A imigração varia muito com a fila.**"],"title":"Estimativa da Rota Certa, não é dado oficial"},{"t":"h","text":"O que sobra de cidade"},{"t":"ul","items":["**10 h entre os voos:** cerca de 2 h 20 na cidade.","**14 h entre os voos:** cerca de 6 h 20.","**19 h 46 entre os voos** (pouso às 12h45, voo às 8h31 do dia seguinte): cerca de 12 h."]},{"t":"tip","items":["Com o aeroporto a cerca de uma hora do centro, sobram menos de 2 horas na cidade. Nesse caso, **fique no aeroporto e descanse**. É uma estimativa da Rota Certa."],"title":"Menos de 10 horas não compensa"},{"t":"h","text":"Entrada, bagagem e guarda-volumes","label":"Passo 2"},{"t":"ul","items":["**Visto:** o Brasil está na lista de isenção. Passaportes ordinários podem viajar à Turquia por até 90 dias sem visto, segundo o Ministério das Relações Exteriores da Turquia (consultado em 23/10/2026).","**Passaporte:** o ministério recomenda validade de pelo menos 6 meses a partir da chegada. A lei exige no mínimo 60 dias além do fim da estadia autorizada.","**Sua mala vai até o destino final?** Confirme no check-in. Se as passagens forem reservas separadas, você terá de retirar a mala, fazer novo check-in e arriscar o voo se atrasar. Nesse caso, deixe uma margem bem maior."]},{"t":"tip","items":["**Pequena (sacola do duty free):** TRY 210 (cerca de R$ 21).","**Média (mala de cabine):** TRY 270 (cerca de R$ 27).","**Grande (mala despachada):** TRY 550 (cerca de R$ 56).","**Onde fica:** o balcão está no piso de chegadas, ao lado da saída de voos domésticos e em frente à saída 13. Há armários perto dos portões 1 e 6, no piso de partidas. Tarifa de 2026 do site oficial do aeroporto.","**Horário:** o site oficial não informa. Ao deixar a mala, pergunte no balcão até que horas ele funciona: se o seu voo sai de manhã cedo, isso decide o plano."],"title":"Guarda-volumes no aeroporto, por 24 horas"},{"t":"h","text":"Do aeroporto à cidade","label":"Passo 3"},{"t":"img","src":"/assets/blog/istambul-escala-aeroporto.jpg","alt":"Saguão de chegada do Aeroporto de Istambul, com a placa Welcome to Istanbul no alto e passageiros de costas indo em direção à escada rolante","caption":"O saguão de chegada do Aeroporto de Istambul.","credit":"Foto: Carlos Victor / Rota Certa","w":1000,"h":750},{"t":"ul","items":["**Metrô, linha M11:** liga o aeroporto a Gayrettepe, onde há conexão com a linha M2 do metrô de Istambul. De lá, siga para o centro: Sultanahmet fica na linha de bonde T1. **Estimativa da Rota Certa:** cerca de 30 a 40 minutos no M11, e 60 a 80 minutos a viagem inteira até o centro.","**Ônibus, Havaist:** são 11 linhas entre o aeroporto e a cidade, com paradas em Taksim e em outros pontos. Os ônibus aceitam cartão de crédito.","**Táxi ou transfer:** o mais simples, o mais caro. Combine o preço antes de entrar no carro, ou reserve um transfer com antecedência."]},{"t":"tip","items":["Deixe o transfer da volta reservado na véspera, em vez de contar com o primeiro metrô."],"title":"Voo de manhã cedo?"},{"t":"p","text":"Linhas e horários atuais: [site do aeroporto](https://www.istairport.com/en/airport/airport-transportation) e [site da Havaist](https://hava.ist)."},{"t":"h","text":"Minha escala de 19 horas","label":"Como foi"},{"t":"p","text":"Pousei às 12h45 e meu voo saiu às 8h31 do dia seguinte. Os horários abaixo vêm dos meus vídeos e fotos. Só entram os que ficaram registrados, e a sua conta do tempo pode ser diferente."},{"t":"img","src":"/assets/blog/istambul-escala-skyline.jpg","alt":"Skyline de Istambul ao entardecer, vista do barco no Bósforo, com a orla iluminada e nuvens escuras no céu","caption":"O skyline de Istambul ao entardecer, visto do barco.","credit":"Foto: Carlos Victor / Rota Certa","w":1000,"h":669},{"t":"ul","items":["**12h47:** Aeroporto de Istambul, chegada.","**13h52 e 15h57:** passeio pela cidade.","**18h06:** barco no Bósforo.","**18h49:** por baixo da ponte Fatih Sultan Mehmet.","**19h29:** pôr do sol perto da Torre da Donzela.","**19h49:** skyline de Istambul do barco.","**20h54:** pátio da Mesquita Azul.","**21h05:** dentro da Mesquita Azul.","**8h31, no dia seguinte:** voo."]},{"t":"h","text":"Roteiros de 10, 14 e 19 horas","label":"Passo 4"},{"t":"p","text":"Sugestões da Rota Certa para o tempo que sobra na cidade, não são dados oficiais."},{"t":"ul","items":["**10 h entre os voos, cerca de 2 h 20 na cidade, só Sultanahmet:** Mesquita Azul e Santa Sofia por fora, uma volta pela praça e de volta. Entrar dentro de uma das duas já é o bastante.","**14 h entre os voos, cerca de 6 h 20 na cidade, Sultanahmet e barco:** Sultanahmet com calma e, no fim da tarde, um passeio de barco no Bósforo. Escolha o barco que volta a tempo do seu transfer.","**19 h 46 entre os voos, cerca de 12 h na cidade, o que eu fiz:** cidade na tarde, barco no Bósforo até o pôr do sol, Torre da Donzela vista da água e a Mesquita Azul à noite, com a hora de dormir antes do voo."]},{"t":"p","text":"[Abrir Mesquita Azul e Santa Sofia no Google Maps, a pé](https://www.google.com/maps/dir/?api=1&origin=Blue%20Mosque%2C%20Istanbul&destination=Hagia%20Sophia%2C%20Istanbul&travelmode=walking)"},{"t":"h","text":"Barco no Bósforo e Torre da Donzela","label":"Fim da tarde"},{"t":"img","src":"/assets/blog/istambul-escala-bosforo.jpg","alt":"Ponte sobre o Bósforo ao fundo, com um navio de carga na água e o céu claro do fim de tarde","caption":"Uma ponte sobre o Bósforo, vista do barco.","credit":"Foto: Carlos Victor / Rota Certa","w":1000,"h":483},{"t":"ul","items":["**Dois jeitos de fazer:** o passeio público da Şehir Hatları sai de Eminönü. Empresas privadas, como Turyol e Dentur, saem de Eminönü e de Kabataş, em passeios circulares de cerca de 1 h 30, com mais saídas ao longo do dia.","**Quanto tempo reservar:** conte de 1 h 30 a 2 h para um passeio curto. O passeio longo, até Anadolu Kavağı, leva cerca de 6 horas e não cabe numa escala.","**Pôr do sol:** no dia 29/08, às 19h29, o sol já estava rente ao horizonte. O horário muda com a época do ano: confira o do seu dia."]},{"t":"tip","items":["O pôr do sol da torre fica lindo visto do convés do barco do Bósforo.","**Para subir:** a entrada de estrangeiros custa € 27 (cerca de R$ 153), mais TRY 75 (cerca de R$ 8) do barco até a ilha, pago à parte."],"title":"Torre da Donzela: por fora, ao pôr do sol"},{"t":"passeio","busca":"Passeio de barco Bósforo Istambul","title":"Passeios de barco no Bósforo"},{"t":"h","text":"Mesquita Azul e Santa Sofia","label":"Sultanahmet"},{"t":"img","src":"/assets/blog/istambul-escala-mesquita-azul.jpg","alt":"Pátio da Mesquita Azul à noite, iluminado, com a fonte de ablução no centro e as cúpulas ao fundo","caption":"O pátio da Mesquita Azul, à noite.","credit":"Foto: Carlos Victor / Rota Certa","w":1000,"h":750},{"t":"ul","items":["**Mesquita Azul, entrada grátis:** é local de culto e fecha para visitas nos cinco horários de oração, por cerca de 60 a 90 minutos cada, e na sexta ao meio-dia. Ombros e joelhos cobertos, e mulheres cobrem o cabelo. Véus grátis na entrada.","**Santa Sofia:** estrangeiros pagam € 25 (cerca de R$ 141) pela galeria superior, valor em vigor desde janeiro de 2024, por decisão do Ministério da Cultura e Turismo. O térreo, de culto, é grátis por uma entrada separada. Na sexta, o horário de visitas muda por causa da oração."]},{"t":"tip","items":["Os horários mudam com a época do ano e com as orações. Veja o quadro na entrada ou um aplicativo de horários de oração."],"title":"Confira o horário no dia"},{"t":"passeio","busca":"Mesquita Azul Santa Sofia Istambul","title":"Passeios em Sultanahmet"},{"t":"h","text":"A volta ao aeroporto","label":"Passo 5"},{"t":"p","text":"É aqui que a escala dá errado. **Comece a voltar antes do que parece necessário.**"},{"t":"ul","items":["**Faça a conta ao contrário:** horário do voo, menos 3 h no aeroporto, menos o trajeto (1 h 20), menos uma margem de 30 minutos. Esse é o horário em que você precisa sair do centro.","**Combine o transporte antes:** reserve o transfer ou o táxi na véspera, principalmente se o voo for de manhã cedo e o metrô ainda não estiver funcionando.","**Nada de último passeio:** quem perde o voo por atraso próprio normalmente paga a diferença de uma nova passagem. Saia do centro no horário que a conta indicou.","**Mala em guarda-volumes?** Retire antes de seguir para o check-in."]},{"t":"h","text":"Quanto custa e checklist","label":"Valores"},{"t":"tip","items":["**Guarda-volumes, 24 h:** pequeno TRY 210 (cerca de R$ 21), médio TRY 270 (cerca de R$ 27), grande TRY 550 (cerca de R$ 56).","**Mesquita Azul:** grátis.","**Santa Sofia, galeria superior:** € 25 (cerca de R$ 141).","**Torre da Donzela:** entrada € 27 (cerca de R$ 153) e barco TRY 75 (cerca de R$ 8).","Conversão pela cotação de venda do Banco Central de 22/10/2026: R$ 0,1015 por lira turca e R$ 5,6494 por euro."],"title":"Quanto custa o passeio"},{"t":"tip","items":["Passaporte com validade (6 meses recomendados).","Mala despachada até o destino final, confirmada.","Conta do tempo feita e horário de saída do centro anotado.","Transfer ou transporte da volta definido.","Cartão internacional e algum dinheiro em lira.","Roupa para a mesquita (ombros e joelhos).","Carregador portátil e casaco para o barco."],"title":"Checklist"},{"t":"pdf","href":"/guias/escala-em-istambul.pdf","note":"Leve a conta do tempo, os roteiros e o checklist no celular. Grátis, sem cadastro."},{"t":"tip","items":["**Oficiais:** [visto e passaporte, Ministério das Relações Exteriores da Turquia](https://www.mfa.gov.tr/visa-information-for-foreigners.en.mfa), [guarda-volumes do aeroporto](https://www.istairport.com/en/flights/airport-guides/arrival-passenger-guide/services/other-services/left-luggage-offices-and-storage-lockers), [transporte do aeroporto e metrô M11](https://www.istairport.com/en/airport/airport-transportation) e [Havaist](https://hava.ist).","**Comerciais:** [barcos do Bósforo](https://turkeytravelplanner.com/go/istanbul/sights/bosphorus/ferry.html), [Torre da Donzela](https://istanbul.com/maidens-tower) e [Mesquita Azul](https://istanbul.com/blue-mosque).","**Imprensa:** [Santa Sofia, € 25 para estrangeiros desde 15/01/2024](https://duvarenglish.com/entry-fee-to-be-imposed-on-tourists-visiting-hagia-sophia-news-63649).","**Câmbio:** [boletim de fechamento do Banco Central, 22/10/2026](https://www4.bcb.gov.br/Download/fechamento/20261022.csv)."],"title":"Fontes consultadas em outubro de 2026"},{"t":"tip","items":["**Horário do metrô M11 e tarifas de metrô, Havaist e táxi:** o site do aeroporto não traz e as outras fontes divergem. Confira nos sites oficiais.","**Horário e píer de embarque da Torre da Donzela, e preço do passeio de barco no Bósforo:** as fontes divergem.","**Horário do guarda-volumes:** o site oficial não informa. Pergunte no balcão.","**Regras de oração e de roupa da Mesquita Azul:** vêm de guia de viagem, sem página oficial localizada."],"title":"O que este guia não informa"},{"t":"p","text":"Preços e horários mudam com o tempo: confira nas fontes acima antes de ir. Os tempos de imigração, de trajeto (1 h 20), de antecedência no aeroporto (3 h) e de margem (30 min), e os roteiros de 10, 14 e 19 horas, são estimativas e sugestões da Rota Certa, não dados oficiais. Guia independente da Rota Certa, sem vínculo com os locais citados."},{"t":"p","text":"Foto de capa: Carlos Victor / Rota Certa."},{"t":"whatsapp","title":"Cotar passagem com escala em Istambul","text":"Envie a sua cidade de saída, o mês da viagem e o número de pessoas. A Rota Certa encontra a sua passagem, com a escala que cabe no seu passeio.","label":"Quero cotar minha passagem","message":"Oi, Rota Certa! Vi o guia Escala em Istambul e quero cotar uma passagem com escala em Istambul."},{"t":"p","text":"Quer montar o roteiro da viagem inteira? Use o [Planner grátis da Rota Certa](https://rotacertapassagens.com/#/planner)."},{"t":"contato"},{"t":"afiliado"}]', 8);
